#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, q;
    if (!(std::cin >> n >> q)) return 0;

    std::vector<int> values(n);
    for (int& x : values) std::cin >> x;

    std::sort(values.begin(), values.end());     // once, not per query

    while (q--) {
        int k;
        std::cin >> k;
        std::cout << values[k - 1] << '\n';      // k is 1-based
    }
}
